class Hero {
public:
  Subject& damaged() { return damaged_; }
  Subject& died()    { return died_; }

  void takeDamage(int amount) {
    hp_ -= amount;
    damaged_.notify(*this, EVENT_DAMAGED);
    if (hp_ <= 0) died_.notify(*this, EVENT_DIED);
  }
private:
  Subject damaged_;  // composition, not inheritance
  Subject died_;
  int hp_;
};

