struct ObserverNode {
  Observer* observer;
  ObserverNode* next;
};

class Subject {
public:
  void addObserver(Observer* o) {
    ObserverNode* n = nodePool.acquire();  // pre-allocated pool
    n->observer = o;
    n->next = head_;
    head_ = n;
  }
  void notify(const Entity& e, Event ev) {
    for (ObserverNode* n = head_; n; n = n->next)
      n->observer->onNotify(e, ev);
  }
private:
  ObserverNode* head_ = nullptr;
};

