void PlayerController::jump() {
  if (jumpsLeft_ == 0) return;
  jumpsLeft_--;
  body_.applyImpulse(JUMP_VELOCITY);
  animator_.play(ANIM_JUMP);
  jumped_.notify(*this);   // only unrelated systems listen
}

